def _diagonal_probabilities(amplitudes: Any, size: int, measured: list[int]) -> list[float]:
    """提取 measured 量子位的计算基测量边缘概率。

    ``amplitudes`` 可以是状态向量（模平方）或已旋转到测量基的密度矩阵
    （对角元）；结果按 measured 量子位构成的位串索引（measured[0] 为
    最高位），长度为 ``2 ** len(measured)``。
    """
    width = len(measured)
    probabilities = [0.0] * (1 << width)
    if width == 0:
        diagonal = amplitudes
        probabilities[0] = (
            sum(x.real * x.real + x.imag * x.imag for x in diagonal)
            if isinstance(amplitudes[0], complex) else sum(diagonal)
        )
        return probabilities
    masks = [1 << q for q in measured]
    for b in range(size):
        outcome = 0
        for k, mask in enumerate(masks):
            if b & mask:
                outcome |= 1 << (width - 1 - k)
        if isinstance(amplitudes[0], complex):
            amp = amplitudes[b]
            probabilities[outcome] += amp.real * amp.real + amp.imag * amp.imag
        else:
            probabilities[outcome] += amplitudes[b * size + b].real
    return probabilities

